import {TRIALS} from '../content/trials.js?v=0.9.0';
import {ROUTES,INCIDENTS,RELICS,activeRelic} from '../content/journeys.js?v=0.6.0';
import {ZONES,ITEM_TEMPLATES} from '../content/region.js?v=0.3.1';
import {DUNGEONS} from '../content/adventures.js?v=0.3.1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const group=items=>{let result=[];for(let i of items){const t=ITEM_TEMPLATES[i.template];let stack=['material','consumable','card'].includes(t.kind)&&result.find(g=>g.template===i.template);if(stack)stack.count++;else result.push({...i,count:1});}return result;};
export function renderJourneyPanel(name,h,s){
 if(name==='storage'){
  const list=(items,direction)=>group(items).map(i=>{const t=ITEM_TEMPLATES[i.template];return `<article class="storage-row"><div><b>${esc(t.name)}${i.quality?' +'+i.quality:''}</b><small>${i.count>1?'×'+i.count+' · ':''}${esc(t.kind==='quest'?'Квестовий':t.bound?'Особистий предмет':t.desc||'')}</small></div><button class="btn secondary" data-storage-move="${i.id}" data-direction="${direction}" data-count="1">${direction==='deposit'?'Покласти':'Забрати'} 1</button>${i.count>1?`<button class="btn secondary" data-storage-move="${i.id}" data-direction="${direction}" data-count="${i.count}">Усі ×${i.count}</button>`:''}</article>`}).join('')||'<p class="empty">Поки порожньо.</p>';
  return{title:'Скриня мандрівника',html:`<p class="notice">Сховище: ${h.storage?.length||0}/500. Речі доступні у скринях Вербової слободи, передмістя Багряного замку та зимового двору. ID, гартування й руни зберігаються. Квестові предмети лишаються в торбі.</p><button class="btn" data-storage-materials="yes">Покласти всі вільні матеріали</button><div class="storage-columns"><section><h3>Торба · ${h.inventory.length}</h3>${list(h.inventory.filter(i=>!Object.values(h.equipment).includes(i.id)&&ITEM_TEMPLATES[i.template].kind!=='quest'),'deposit')}</section><section><h3>Сховище · ${h.storage?.length||0}</h3>${list(h.storage||[],'withdraw')}</section></div>`};
 }
 if(name==='rewards')return{title:'Нагороди експедицій',html:`<p class="notice">Оберіть одну нагороду з кожного проходження. Отримати її можна біля переможеного боса, привалу або сховища. Класові реліквії займають комірку аксесуара: одночасно працює одна.</p>${(h.dungeonRewards||[]).map(r=>`<section class="reward-selection"><h3>${r.trial?'Випробування '+TRIALS[r.trial].name+' · ':''}${esc(ZONES[r.zone]?.name)} · ${esc(ROUTES[r.route]?.name||'Експедиція')}</h3><div class="reward-grid">${r.choices.map(choice=>{const t=ITEM_TEMPLATES[choice];return `<article class="card"><span class="tag">${['resources','trial-resources'].includes(choice)?'РЕСУРСИ':'КЛАСОВА РЕЛІКВІЯ'}</span><h3>${['resources','trial-resources'].includes(choice)?'Припаси мандрівника':esc(t.name)}</h3><p>${['resources','trial-resources'].includes(choice)?`${r.trial?8+r.trial*2:r.route==='risky'?6:4} жар-уламки, ${r.trial?5+r.trial*2:r.route==='risky'?4:3} відлуння, ${r.trial?800+r.level*15:400+r.level*10} Z.`:esc(t.desc)}</p><button class="btn" data-dungeon-choice="${r.id}" data-choice="${choice}">Обрати цю нагороду</button></article>`}).join('')}</div></section>`).join('')||'<p>Немає неотриманих нагород. Завершіть будь-яку з чотирьох експедицій.</p>'}`};
 if(name==='relics'){const r=activeRelic(h);return{title:'Реліквії вашого класу',html:`<p class="notice">Активна: ${r?esc(r.name):'немає'}. Отримання — вибір фінальної нагороди данжу. Споряджайте через торбу; зміна аксесуара змінює поведінку навички.</p><div class="reward-grid">${RELICS[h.classId].map(r=>`<article class="card"><h3>${esc(r.name)}</h3><p>${esc(r.desc)}</p><p>Від рівня 20 · +60 HP · +20 SP</p></article>`).join('')}</div>`};}
 if(name==='dungeon'){
  const d=DUNGEONS[s.zone];if(!d)return{title:'Експедиції Вирію',html:`<p>Повторні данжі є у синіх копальнях (24+), Багряних залах (30+), підземеллі замку (35+) та крижаній крипті (62+).</p><button class="btn secondary" data-open="map">Показати карту</button>`};
  const run=s.dungeonRun,remaining=run?.guards?.filter(id=>s.enemies.some(e=>e.id===id&&!e.dead)).length??3;
  return{title:d.name,html:`<button class="btn secondary" data-open="trials">Зоряні випробування · 40+</button><p class="notice">Від рівня ${d.level}. Три вартові відкривають боса. Вороги не відроджуються під час проходження; вихід скасовує експедицію. Наприкінці — одна нагорода з трьох, окрім луту боса й базових ресурсів.</p><p>${run?.status==='active'?`${run.trial?'Випробування '+TRIALS[run.trial].name+' · лікування '+Math.round(TRIALS[run.trial].healing*100)+'% · ':''}Маршрут: ${ROUTES[run.route||'safe'].name} · вартових залишилось ${remaining}/3 · ${Math.floor((s.clock-run.started)/60)} хв`:run?.status==='completed'?'Перемога! Оберіть нагороду або почніть нове проходження.':run?.status==='failed'?'Група полягла. Можна повторити.':'Оберіть шлях біля вхідного привалу.'}</p><div class="reward-grid">${Object.entries(ROUTES).map(([id,r])=>`<article class="card"><span class="tag">${id==='risky'?'РИЗИК + НАГОРОДА':'БЕЗПЕЧНІШИЙ МАРШРУТ'}</span><h3>${r.name}</h3><p>${r.desc}</p><button class="btn" data-dungeon-start="${id}" ${run?.status==='active'?'disabled':''}>Почати цей маршрут</button></article>`).join('')}</div><button class="btn secondary" data-open="rewards">Забрати нагороди · ${h.dungeonRewards?.length||0}</button>`};
 }
 if(name==='journey'){
  const object=ZONES[s.zone].objects.find(o=>o.kind==='journey');if(!object)return{title:'Події на стежці',html:'<p>Шукайте події біля привалів у відкритих землях.</p>'};
  const data=INCIDENTS[object.incident],event=s.travelEvent?.zone===s.zone?s.travelEvent:null,cooldown=Math.max(0,(s.journeyCooldowns?.[s.zone]||0)-s.clock),status=event?.status==='active'?'active':cooldown>0?(event?.status||'cooldown'):'available';
  const statusText={active:`Залишилось ${Math.max(0,Math.ceil((event?.expires||0)-s.clock))} с · ворогів ${event?.enemyIds.filter(id=>s.enemies.some(e=>e.id===id&&!e.dead)).length||0}`,completed:'Подію завершено.',skipped:'Ви вирішили не втручатися.',failed:'Подію втрачено.',cooldown:`Нові сліди через ${Math.ceil(cooldown)} с.`}[status]||'Оберіть рішення.';
  return{title:data.name,html:`<p class="dialogue">${data.text}</p><p class="notice">${statusText}</p>${status==='available'?`<div class="reward-grid">${data.choices.map(c=>`<article class="card"><h3>${c.name}</h3><p>${c.desc}</p><button class="btn" data-journey-choice="${object.id}" data-choice="${c.id}">Обрати</button></article>`).join('')}</div><button class="btn secondary" data-journey-choice="${object.id}" data-choice="leave">Пройти повз</button>`:'<p>Завершення зберігається. Після виходу подію не можна миттєво почати знову.</p>'}`};
 }
 return null;
}
